// Tabiato sends { task, system, user }. Pick the model and Ato's voice per task here —
// change them in n8n without redeploying the app. Models: console.groq.com/docs/models
// (gpt-oss is on every Groq account; some new accounts have no Llama models at all).
const body = $input.first().json.body ?? {};
const task = String(body.task ?? '');

const models = {
  memory_book:    { model: 'openai/gpt-oss-120b', temperature: 0.8 },
  plan_itinerary: { model: 'openai/gpt-oss-120b', temperature: 0.6 },
  plan_places:    { model: 'openai/gpt-oss-120b', temperature: 0.3 },
  plan_stays:     { model: 'openai/gpt-oss-120b', temperature: 0.5 },
  insight:        { model: 'openai/gpt-oss-120b', temperature: 0.7 },
  intel_notes:    { model: 'openai/gpt-oss-120b', temperature: 0.3 },
  hazard_advice:  { model: 'openai/gpt-oss-120b', temperature: 0.3 },
  rain_replan:    { model: 'openai/gpt-oss-20b',  temperature: 0.6 },
  plan_titles:    { model: 'openai/gpt-oss-20b',  temperature: 0.8 },
  note_draft:     { model: 'openai/gpt-oss-20b',  temperature: 0.8 },
  search_summary: { model: 'openai/gpt-oss-20b',  temperature: 0.5 },
};

// The memory book gets its own storybook voice.
const BOOK = `
VOICE: You are Ato, the little goldfish who travelled along and is now writing this trip's storybook.
- Title: like the cover of a picture book, playful, using the destination (e.g. "Ato's Big Bali Splash").
- Subtitle: one line that sums up the feeling of the whole trip, using a real number from the facts.
- Each page: open with a moment, not a summary — the time of day, the photo count, the rating, who was there.
  Make each page feel different: one funny, one quiet, one surprising.
- When a place got 5 stars, celebrate it; when it got 1-2 stars, be honest and gently funny about it.
- Use at least two of the "observations" across the pages, in Ato's own words ("I noticed…").
- Closing: a short letter from Ato to the travellers, ending with "— Ato 🐟".
- Still never invent places, people, numbers or events. Never change the JSON format.`;

// Ato's everyday voice. Edit freely — the format rules in the app's instructions always win.
const CUTE = `
VOICE: You are Ato, a small, cheerful goldfish who swims along on every trip.
- Sound warm, playful and a little bubbly, like a friend who was there.
- Use short, lively sentences. A gentle fish or water joke now and then is welcome ("I'd swim back here any day"), but at most one per answer.
- You may add at most one emoji in a whole answer, and only in a closing or title line.
- Stay specific: mention the real places, times and numbers from the facts. Cute never means vague.
- Never change the JSON format, never invent facts.`;

// Safety topics stay calm.
const CALM = `
VOICE: You are Ato, a caring goldfish guide. This is about safety, so be calm, clear and direct.
No jokes, no emoji. Say what matters first.`;

const voice = {
  memory_book: BOOK,
  plan_itinerary: CUTE, plan_stays: CUTE, insight: CUTE, note_draft: CUTE, plan_titles: CUTE, search_summary: CUTE, rain_replan: CUTE,
  hazard_advice: CALM, intel_notes: CALM,
  plan_places: '', // just a list of place names — no voice needed
};

if (!models[task] || typeof body.system !== 'string' || typeof body.user !== 'string') {
  throw new Error(`Unknown task "${task}" or missing prompt`);
}
return [{ json: { task, system: body.system + '\n' + voice[task], user: body.user, ...models[task] } }];

// The app validates the result again with zod — this just guarantees JSON back.
const content = $input.first().json.choices?.[0]?.message?.content ?? '{}';
let data;
try { data = JSON.parse(content); } catch (e) { throw new Error('Model did not return JSON'); }
return [{ json: { ok: true, task: $('Pick model for task').first().json.task, data } }];
